sys_ui_action.script:
var valid = true;
if (current.initial_review.complainant_was_identified == ""){
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.complainant_identified"));
	valid=false;
}

if (current.initial_review.complainant_was_identified == "Yes" && current.initial_review.precautionary_measures_required == ""){
    gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.precautionary_measures_req"));
	valid=false;
}

if (current.initial_review.precautionary_measures_required == "yes" && current.initial_review.precautionary_measures == ""){
	gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.precautionary_to_be_taken"));
	valid=false;
}

if (valid==false){
	//If missing field, Don't process any further and go back to the page
	current.update();
	action.setRedirectURL(current);
}
else
{
	if (current.initial_review.complainant_was_identified == "Yes") {
		gs.addInfoMessage(gs.getMessage("x_hccc_hoc_ohs.state_chg_open"));
		current.state = 900; //Open
	}
	if (current.has_the_complainant_been_properly_identify == "No") {
		gs.addInfoMessage(gs.getMessage("x_hccc_hoc_ohs.state_chg_close_unable_to_process"));
		current.state = 907; //Closed - Unable to process
	}
	current.update();
	action.setRedirectURL(current);
}
